import { existsSync, lstatSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const runtimeNames = Object.freeze(['api.mjs', 'contract.mjs', 'run.mjs', 'runtime.mjs', 'service.mjs']);

// Normalize checkout line endings so generated bytes agree across Windows and Linux.
export function buildBundle({ source = join(root, 'scripts/issue-submission'),
  output = join(root, 'skills/create-issue/scripts'), check = false } = {}) {
  const files = runtimeNames.map(name => [name, Buffer.from(readFileSync(join(source, name), 'utf8').replaceAll('\r\n', '\n'))]);
  if (existsSync(output)) {
    if (!lstatSync(output).isDirectory() || lstatSync(output).isSymbolicLink()) throw new Error('Bundle output must be a real directory.');
    for (const entry of readdirSync(output, { withFileTypes: true })) {
      if (!runtimeNames.includes(entry.name) || !entry.isFile()) throw new Error(`Unexpected bundle entry: ${entry.name}; inspect it manually.`);
    }
  } else if (check) throw new Error('Missing issue-submission bundle; run node scripts/build-issue-submission.mjs');
  else mkdirSync(output, { recursive: true });
  for (const [name, bytes] of files) {
    const target = join(output, name);
    if (check) {
      if (!existsSync(target) || !readFileSync(target).equals(bytes)) throw new Error(`Stale issue-submission bundle: ${name}; run node scripts/build-issue-submission.mjs`);
    } else writeFileSync(target, bytes);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = process.argv.slice(2);
  if (args.length > 1 || (args.length === 1 && args[0] !== '--check')) throw new Error('Usage: node scripts/build-issue-submission.mjs [--check]');
  buildBundle({ check: args.includes('--check') });
  console.log(args.includes('--check') ? 'Issue-submission bundle matches maintained sources.' : 'Built self-contained issue-submission bundle.');
}
